	static SafetyRule hideRule(MenuEntry entry)
	{
		return hideRule(entry, -1, -1);
	}

	static SafetyRule hideRule(MenuEntry entry, int selectedItemId, int resolvedObjectId)
	{
		if (entry == null)
		{
			return null;
		}
		int item = itemId(entry);
		if (item <= 0)
		{
			item = selectedItemId;
		}
		int object = resolvedObjectId > 0 ? resolvedObjectId : objectId(entry);
		return hideRule(entry.getType(), npcId(entry), item, object, entry.getOption(), true);
	}

	static SafetyRule hideRule(MenuEntry entry, int selectedItemId, int resolvedObjectId, boolean hasHarpoon)
	{
		if (entry == null)
		{
			return null;
		}
		int item = itemId(entry);
		if (item <= 0)
		{
			item = selectedItemId;
		}
		int object = resolvedObjectId > 0 ? resolvedObjectId : objectId(entry);
		return hideRule(entry.getType(), npcId(entry), item, object, entry.getOption(), hasHarpoon);
	}

	static SafetyRule hideRule(MenuAction type, int npcId, int itemId, int objectId, String option)
	{
		return hideRule(type, npcId, itemId, objectId, option, true);
	}

	static SafetyRule hideRule(MenuAction type, int npcId, int itemId, int objectId, String option, boolean hasHarpoon)
	{
		if (type == null || SafetyIds.isWalkOrCancel(type) || SafetyIds.isExamine(type))
		{
			return null;
		}
		if (SafetyIds.DUMMY_NPCS.contains(npcId) && SafetyIds.isNpcOp(type))
		{
			return COMBAT_DUMMY;
		}
		if (SafetyIds.DUMMY_OBJECTS.contains(objectId) && SafetyIds.isObjectOp(type))
		{
			return COMBAT_DUMMY;
		}
		if (SafetyIds.CANNONS.contains(objectId)
			&& (op(option, "Fire") || SafetyIds.isUseOnObject(type)))
		{
			return COMBAT_CANNON;
		}
		if (SafetyIds.BLAST_FURNACE_PUMPS.contains(objectId) && SafetyIds.isObjectOp(type))
		{
			return COMBAT_PUMP;
		}
		if (SafetyIds.BARBARIAN_FISHING_SPOTS.contains(npcId) && SafetyIds.isNpcOp(type))
		{
			return COMBAT_BARB_FISH;
		}
		if (SafetyIds.HARPOON_FISHING_SPOTS.contains(npcId) && SafetyIds.isNpcOp(type)
			&& op(option, "Harpoon") && !hasHarpoon)
		{
			return COMBAT_BAREHAND;
		}
		if (SafetyIds.POH_LECTERNS.contains(objectId)
			&& (SafetyIds.isUseOnObject(type) || (SafetyIds.isObjectOp(type) && op(option, "Study"))))
		{
			return COMBAT_LECTERN;
		}
		if (SafetyIds.POH_RANGING_GAMES.contains(objectId) && SafetyIds.isObjectOp(type)
			&& !SafetyIds.isConstructionOp(option))
		{
			return COMBAT_DARTBOARD;
		}
		if (SafetyIds.MISCLICK_NPCS.contains(npcId) && SafetyIds.isNpcOp(type))
		{
			return NPC_MISCLICK;
		}
		if (SafetyIds.TAMAYU.contains(npcId) && SafetyIds.isNpcOp(type))
		{
			return NPC_MISCLICK;
		}
		if (SafetyIds.EVIL_BOB.contains(npcId) && SafetyIds.isNpcOp(type))
		{
			return NPC_MISCLICK;
		}
		if (SafetyIds.INFORMATION_CLERK.contains(npcId) && SafetyIds.isNpcOp(type))
		{
			return NPC_MISCLICK;
		}
		if (objectId == SafetyIds.OLD_MEMORIAL
			&& (SafetyIds.isObjectOp(type) || type == MenuAction.ITEM_USE_ON_GAME_OBJECT
			|| type == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
			&& !op(option, "Reminisce"))
		{
			return MEMOIRS_CHARGE;
		}
		if (SafetyIds.MEMOIRS.contains(itemId) && op(option, "Charge"))
		{
			return MEMOIRS_CHARGE;
		}
		if (SafetyIds.BONES.contains(itemId) && (op(option, "Bury") || op(option, "Take")))
		{
			return PRAYER_REMAINS;
		}
		if (SafetyIds.ASHES.contains(itemId) && (op(option, "Scatter") || op(option, "Take")))
		{
			return PRAYER_REMAINS;
		}
		if (SafetyIds.NIGHTSHADE.contains(itemId) && op(option, "Eat"))
		{
			return PRAYER_NIGHTSHADE;
		}
		if (SafetyIds.SHARD_BREAKDOWN.contains(itemId) && op(option, "Break-down"))
		{
			return PRAYER_LIBATION;
		}
		if (SafetyIds.PRAYER_ALTARS.contains(objectId) && SafetyIds.isUseOnObject(type))
		{
			return PRAYER_ALTAR;
		}
		if (SafetyIds.PRAYER_ALTARS.contains(objectId) && SafetyIds.isObjectOp(type)
			&& (op(option, "Offer") || optionContains(option, "offer")))
		{
			return PRAYER_ALTAR;
		}
		if (SafetyIds.LIBATION_BOWLS.contains(objectId)
			&& (SafetyIds.isUseOnObject(type) || (SafetyIds.isObjectOp(type) && !isCheckOption(option))))
		{
			return PRAYER_LIBATION;
		}
		if (SafetyIds.EXPOSED_ALTARS.contains(objectId)
			&& (SafetyIds.isUseOnObject(type) || op(option, "Bless")))
		{
			return PRAYER_LIBATION;
		}
		if (SafetyIds.SACRED_BONE_BURNERS.contains(objectId)
			&& (SafetyIds.isUseOnObject(type) || (SafetyIds.isObjectOp(type) && !isCheckOption(option))))
		{
			return PRAYER_BONE_BURNER;
		}
		if (SafetyIds.CAMDOZAAL_ALTARS.contains(objectId)
			&& (SafetyIds.isUseOnObject(type) || optionContains(option, "offer")))
		{
			return PRAYER_CAMDOZAAL;
		}
		if (SafetyIds.BIRD_EGG_SHRINES.contains(objectId)
			&& (SafetyIds.isUseOnObject(type) || optionContains(option, "offer")))
		{
			return PRAYER_EGG_SHRINE;
		}
		if (SafetyIds.PYRAMID_SARCOPHAGUS.contains(objectId) && SafetyIds.isObjectOp(type) && op(option, "Open"))
		{
			return PRAYER_SARCOPHAGUS;
		}
		return null;
	}

	static SafetyRule warnRule(MenuEntry entry)
	{
		if (entry == null)
		{
			return null;
		}
		return warnRule(entry.getType(), npcId(entry), itemId(entry), entry.getOption());
	}

	static SafetyRule warnRule(MenuAction type, int npcId, int itemId, String option)
	{
		if (type == null || SafetyIds.isWalkOrCancel(type) || SafetyIds.isExamine(type))
		{
			return null;
		}
		if (SafetyIds.isNpcOp(type) && SafetyIds.INFORMATION_CLERK.contains(npcId))
		{
			return CLERK_PRAYER;
		}
		if (SafetyIds.isNpcOp(type) && (SafetyIds.TAMAYU.contains(npcId)
			|| SafetyIds.JUNA.contains(npcId)
			|| SafetyIds.OTTO.contains(npcId)
			|| SafetyIds.ELNOCK.contains(npcId)
			|| SafetyIds.FATHER_AERECK.contains(npcId)))
		{
			return XP_TRAP_NPC;
		}
		return null;
	}

	enum SpellbookOp
	{
		HIDE,
		KEEP,
		NONE
	}

	static SpellbookOp spellbookOp(MenuEntry entry)
	{
		if (entry == null)
		{
			return SpellbookOp.NONE;
		}
		return spellbookOp(entry.getWidget(), entry.getOption());
	}

	static SpellbookOp spellbookOp(Widget widget)
	{
		return spellbookOp(widget, "");
	}

	private static SpellbookOp spellbookOp(Widget widget, String option)
	{
		Widget current = widget;
		for (int depth = 0; depth < 6 && current != null; depth++)
		{
			int id = current.getId();
			if (WidgetUtil.componentToInterface(id) != InterfaceID.MAGIC_SPELLBOOK)
			{
				return SpellbookOp.NONE;
			}
			SpellbookOp op = spellbookOp(id, current.getParentId(), option);
			if (op != SpellbookOp.NONE)
			{
				return op;
			}
			current = current.getParent();
		}
		return SpellbookOp.NONE;
	}

	static SpellbookOp spellbookOp(int widgetId, int parentId, String option)
	{
		if (WidgetUtil.componentToInterface(widgetId) != InterfaceID.MAGIC_SPELLBOOK)
		{
			return SpellbookOp.NONE;
		}
		if (ZERO_XP_SPELL_WIDGETS.contains(widgetId))
		{
			return SpellbookOp.KEEP;
		}
		if (parentId != InterfaceID.MagicSpellbook.SPELLLAYER)
		{
			return SpellbookOp.NONE;
		}
		if (op(option, "Configure"))
		{
			return SpellbookOp.KEEP;
		}
		return SpellbookOp.HIDE;
	}

	static boolean isSpellbookXpOp(int widgetId, int parentId, String option)
	{
		return spellbookOp(widgetId, parentId, option) == SpellbookOp.HIDE;
	}

	static boolean isTabletCraftXpOp(Widget widget)
	{
		if (widget == null)
		{
			return false;
		}
		Widget current = widget;
		for (int depth = 0; depth < 6 && current != null; depth++)
		{
			if (TABLET_CRAFT_WIDGETS.contains(current.getId()))
			{
				return true;
			}
			if (WidgetUtil.componentToInterface(current.getId()) != InterfaceID.TELETABS_CRAFT_IF)
			{
				return false;
			}
			current = current.getParent();
		}
		return false;
	}

	static Iterable<Integer> tabletCraftWidgets()
	{
		return TABLET_CRAFT_WIDGETS;
	}

	static boolean isSpellTargetAction(MenuAction type)
	{
		return type == MenuAction.WIDGET_TARGET_ON_NPC
			|| type == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT
			|| type == MenuAction.WIDGET_TARGET_ON_GROUND_ITEM
			|| type == MenuAction.WIDGET_TARGET_ON_WIDGET
			|| type == MenuAction.WIDGET_USE_ON_ITEM;
	}

	private static int npcId(MenuEntry entry)
	{
		NPC npc = entry.getNpc();
		return npc == null ? -1 : npc.getId();
	}

	private static int itemId(MenuEntry entry)
	{
		int id = entry.getItemId();
		if (id > 0)
		{
			return id;
		}
		if (SafetyIds.isGroundItemOp(entry.getType()))
		{
			return entry.getIdentifier();
		}
		return -1;
	}

	private static int objectId(MenuEntry entry)
	{
		MenuAction type = entry.getType();
		if (SafetyIds.isObjectOp(type)
			|| type == MenuAction.ITEM_USE_ON_GAME_OBJECT
			|| type == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		{
			return entry.getIdentifier();
		}
		return -1;
	}

	private static boolean op(String option, String expected)
	{
		return expected.equalsIgnoreCase(MenuMatcher.strip(option));
	}

	private static boolean optionContains(String option, String fragment)
	{
		return MenuMatcher.strip(option).toLowerCase().contains(fragment.toLowerCase());
	}

	private static boolean isCheckOption(String option)
	{
		String stripped = MenuMatcher.strip(option);
		return "Check".equalsIgnoreCase(stripped) || "Check-Faith".equalsIgnoreCase(stripped);
	}
}

package com.skillerguard;

import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

/** Tells the player once per login/hop why Guard has stood down on an exempt world. */
@Singleton
public class WorldExemptionNotice
{
	private static final Color CHAT_ORANGE = new Color(255, 170, 0);

	private final GuardActivation activation;
	private final SkillerGuardConfig config;
	private final ChatMessageManager chatMessageManager;

	@Inject
	WorldExemptionNotice(GuardActivation activation, SkillerGuardConfig config, ChatMessageManager chatMessageManager)
	{
		this.activation = activation;
		this.config = config;
		this.chatMessageManager = chatMessageManager;
	}

	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN || !config.enabled() || !activation.isOnExemptWorld())
		{
			return;
		}
		chat("[SG] Guard is off on this world. Seasonal, Deadman, and Quest Speedrunning worlds use"
			+ " a character separate from your main account, so there is nothing here for Guard"
			+ " to protect.");
	}

	private void chat(String message)
	{
		String formatted = new ChatMessageBuilder()
			.append(CHAT_ORANGE, message)
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(formatted)
			.build());
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(formatted)
			.build());
	}
}

package com.skillerguard;

import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.Skill;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.Text;

@Singleton
public class LampLockoutService
{
	private static final Map<Skill, Integer> SKILL_WIDGETS = new EnumMap<>(Skill.class);

	static
	{
		SKILL_WIDGETS.put(Skill.ATTACK, InterfaceID.Xpreward.ATTACK);
		SKILL_WIDGETS.put(Skill.STRENGTH, InterfaceID.Xpreward.STRENGTH);
		SKILL_WIDGETS.put(Skill.DEFENCE, InterfaceID.Xpreward.DEFENCE);
		SKILL_WIDGETS.put(Skill.HITPOINTS, InterfaceID.Xpreward.HITPOINTS);
		SKILL_WIDGETS.put(Skill.RANGED, InterfaceID.Xpreward.RANGED);
		SKILL_WIDGETS.put(Skill.MAGIC, InterfaceID.Xpreward.MAGIC);
		SKILL_WIDGETS.put(Skill.PRAYER, InterfaceID.Xpreward.PRAYER);
	}

	private final Client client;
	private final ClientThread clientThread;
	private final SkillerGuardConfig config;
	private final GuardActivation activation;
	private final GuardState state;

	@Inject
	LampLockoutService(
		Client client,
		ClientThread clientThread,
		SkillerGuardConfig config,
		GuardActivation activation,
		GuardState state)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.activation = activation;
		this.state = state;
	}

	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.XPREWARD)
		{
			return;
		}
		clientThread.invoke(this::updateInterface);
	}

	public void refresh()
	{
		clientThread.invoke(this::updateInterface);
	}

	public void restore()
	{
		clientThread.invoke(() -> hideCombatSkills(false));
	}

	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!lampOpen() || !shouldLock())
		{
			return;
		}
		String option = Text.removeTags(event.getMenuOption());
		for (Skill skill : CombatSkills.LAMP_LOCK_ORDER)
		{
			if (skill.getName().equalsIgnoreCase(option))
			{
				event.consume();
				state.warn("Combat skills are locked on this lamp");
				return;
			}
		}
		MenuEntry entry = event.getMenuEntry();
		if (entry != null)
		{
			Widget widget = entry.getWidget();
			if (widget != null && SKILL_WIDGETS.containsValue(widget.getId()))
			{
				event.consume();
				state.warn("Combat skills are locked on this lamp");
			}
		}
	}

	private void updateInterface()
	{
		if (!lampOpen())
		{
			state.setLampCombatOnly(false);
			return;
		}
		boolean lock = shouldLock();
		hideCombatSkills(lock);
		state.setLampCombatOnly(lock && onlyCombatSkillsVisible());
	}

	private boolean shouldLock()
	{
		return activation.isActive() && config.lampLockout();
	}

	private boolean lampOpen()
	{
		Widget root = client.getWidget(InterfaceID.Xpreward.UNIVERSE);
		return root != null && !root.isHidden();
	}

	private void hideCombatSkills(boolean hide)
	{
		for (int componentId : SKILL_WIDGETS.values())
		{
			Widget widget = client.getWidget(componentId);
			if (widget != null)
			{
				widget.setHidden(hide);
			}
		}
	}

	private boolean onlyCombatSkillsVisible()
	{
		Widget root = client.getWidget(InterfaceID.Xpreward.UNIVERSE);
		if (root == null)
		{
			return false;
		}
		Widget[] children = root.getStaticChildren();
		if (children == null)
		{
			return false;
		}
		int visibleSkills = 0;
		int visibleCombat = 0;
		for (Widget child : children)
		{
			String[] actions = child.getActions();
			if (actions == null || actions.length == 0 || actions[0] == null)
			{
				continue;
			}
			Skill skill = skillNamed(actions[0]);
			if (skill == null)
			{
				continue;
			}
			visibleSkills++;
			if (CombatSkills.isCombat(skill))
			{
				visibleCombat++;
			}
		}
		return visibleSkills > 0 && visibleSkills == visibleCombat;
	}

	private static Skill skillNamed(String action)
	{
		for (Skill skill : Skill.values())
		{
			if (skill.getName().equalsIgnoreCase(action))
			{
				return skill;
			}
		}
		return null;
	}
}

package com.skillerguard;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.api.ChatMessageType;
import net.runelite.api.ObjectComposition;
import net.runelite.api.widgets.Widget;

@Singleton
public class MenuSafetyService
{
	private static final Duration WARN_COOLDOWN = Duration.ofSeconds(8);

	private final Client client;
	private final SkillerGuardConfig config;
	private final GuardActivation activation;
	private final GuardState state;
	private final ChatMessageManager chatMessageManager;
	private final Map<String, Instant> lastWarn = new HashMap<>();

	@Inject
	MenuSafetyService(
		Client client,
		SkillerGuardConfig config,
		GuardActivation activation,
		GuardState state,
		ChatMessageManager chatMessageManager)
	{
		this.client = client;
		this.config = config;
		this.activation = activation;
		this.state = state;
		this.chatMessageManager = chatMessageManager;
	}

	public void onPostMenuSort(PostMenuSort event)
	{
		if (!activation.isActive() || client.isMenuOpen())
		{
			return;
		}
		filterMenu();
	}

	public void onMenuOpened(MenuOpened event)
	{
		if (!activation.isActive())
		{
			return;
		}
		MenuEntry[] filtered = filter(event.getMenuEntries());
		if (filtered.length != event.getMenuEntries().length)
		{
			event.setMenuEntries(filtered);
		}
		addRightClickWarnings(filtered);
	}

	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!activation.isActive())
		{
			return;
		}
		MenuEntry entry = event.getMenuEntry();
		if (entry != null && isPlayerEntry(entry))
		{
			return;
		}
		SafetyRule hide = findHide(entry);
		if (hide != null)
		{
			event.consume();
			chat("Blocked: " + hide.getReason());
			state.warn(hide.getReason());
		}
	}

	private void filterMenu()
	{
		Menu menu = client.getMenu();
		if (menu == null)
		{
			return;
		}
		MenuEntry[] current = menu.getMenuEntries();
		MenuEntry[] filtered = filter(current);
		if (filtered.length != current.length)
		{
			menu.setMenuEntries(filtered);
		}
	}

	MenuEntry[] filter(MenuEntry[] entries)
	{
		List<MenuEntry> kept = new ArrayList<>(entries.length);
		List<MenuEntry> protectedEntries = new ArrayList<>();
		for (MenuEntry entry : entries)
		{
			if (isProtected(entry))
			{
				protectedEntries.add(entry);
				kept.add(entry);
				continue;
			}
			if (findHide(entry) == null)
			{
				kept.add(entry);
			}
		}
		if (kept.isEmpty())
		{
			return protectedEntries.toArray(new MenuEntry[0]);
		}
		return kept.toArray(new MenuEntry[0]);
	}

	/**
	 * XP-trap warnings go on the right-click menu instead of chat, so hovering does not spam.
	 */
	private void addRightClickWarnings(MenuEntry[] entries)
	{
		Set<String> reasons = new LinkedHashSet<>();
		for (MenuEntry entry : entries)
		{
			if (isProtected(entry))
			{
				continue;
			}
			SafetyRule warn = findWarn(entry);
			if (warn != null)
			{
				reasons.add(warn.getReason());
			}
		}
		for (String reason : reasons)
		{
			String message = reason;
			client.createMenuEntry(-1)
				.setOption("[SG] " + message)
				.setTarget("")
				.setType(MenuAction.RUNELITE)
				.onClick(e ->
				{
					rateLimitedChat("Careful: " + message, message);
					state.warn(message);
				});
		}
	}

	private boolean isProtected(MenuEntry entry)
	{
		if (isPlayerEntry(entry))
		{
			return true;
		}
		return SafetyIds.isWalkOrCancel(entry.getType()) || SafetyIds.isExamine(entry.getType());
	}

	private boolean isPlayerEntry(MenuEntry entry)
	{
		if (entry.getPlayer() != null)
		{
			return true;
		}
		MenuAction type = entry.getType();
		return type == MenuAction.PLAYER_FIRST_OPTION
			|| type == MenuAction.PLAYER_SECOND_OPTION
			|| type == MenuAction.PLAYER_THIRD_OPTION
			|| type == MenuAction.PLAYER_FOURTH_OPTION
			|| type == MenuAction.PLAYER_FIFTH_OPTION
			|| type == MenuAction.PLAYER_SIXTH_OPTION
			|| type == MenuAction.PLAYER_SEVENTH_OPTION
			|| type == MenuAction.PLAYER_EIGHTH_OPTION
			|| type == MenuAction.WIDGET_TARGET_ON_PLAYER
			|| type == MenuAction.ITEM_USE_ON_PLAYER;
	}

	private SafetyRule findHide(MenuEntry entry)
	{
		if (entry == null)
		{
			return null;
		}
		if (config.hideCombatTraining())
		{
			switch (SafetyCatalog.spellbookOp(entry))
			{
				case HIDE:
					return SafetyCatalog.SPELLBOOK_HIDE;
				case KEEP:
					return null;
				default:
					break;
			}
			if (SafetyCatalog.isSpellTargetAction(entry.getType())
				&& SafetyCatalog.spellbookOp(client.getSelectedWidget()) == SafetyCatalog.SpellbookOp.HIDE)
			{
				return SafetyCatalog.SPELLBOOK_HIDE;
			}
			if (SafetyCatalog.isTabletCraftXpOp(entry.getWidget()))
			{
				return SafetyCatalog.COMBAT_LECTERN;
			}
		}
		SafetyRule hide = SafetyCatalog.hideRule(
			entry, selectedItemId(), resolvedObjectId(entry), hasHarpoon());
		if (hide != null && packEnabled(hide) && shouldHide(hide))
		{
			return hide;
		}
		return null;
	}

	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.TELETABS_CRAFT_IF)
		{
			return;
		}
		hideTabletCraftButtons(activation.isActive() && config.hideCombatTraining());
	}

	public void hideTabletCraftButtons(boolean hide)
	{
		for (int componentId : SafetyCatalog.tabletCraftWidgets())
		{
			Widget widget = client.getWidget(componentId);
			if (widget != null)
			{
				widget.setHidden(hide);
			}
		}
	}

	private boolean hasHarpoon()
	{
		return containsHarpoon(client.getItemContainer(InventoryID.INV))
			|| containsHarpoon(client.getItemContainer(InventoryID.WORN));
	}

	private static boolean containsHarpoon(ItemContainer container)
	{
		if (container == null)
		{
			return false;
		}
		for (Item item : container.getItems())
		{
			if (item != null && SafetyIds.isHarpoon(item.getId()))
			{
				return true;
			}
		}
		return false;
	}

	private int selectedItemId()
	{
		Widget widget = client.getSelectedWidget();
		if (widget == null)
		{
			return -1;
		}
		return widget.getItemId();
	}

	/**
	 * POH furniture is often a hotspot whose real altar id is the impostor.
	 */
	private int resolvedObjectId(MenuEntry entry)
	{
		MenuAction type = entry.getType();
		if (!SafetyIds.isObjectOp(type)
			&& type != MenuAction.ITEM_USE_ON_GAME_OBJECT
			&& type != MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		{
			return -1;
		}
		int id = entry.getIdentifier();
		try
		{
			ObjectComposition def = client.getObjectDefinition(id);
			if (def != null && def.getImpostorIds() != null)
			{
				ObjectComposition impostor = def.getImpostor();
				if (impostor != null)
				{
					return impostor.getId();
				}
			}
		}
		catch (Exception ignored)
		{
			// Impostor lookup needs varbits that are not always present.
		}
		return id;
	}

	private SafetyRule findWarn(MenuEntry entry)
	{
		SafetyRule warn = SafetyCatalog.warnRule(entry);
		if (warn == null || !packEnabled(warn) || shouldHide(warn))
		{
			return null;
		}
		return warn;
	}

	private boolean shouldHide(SafetyRule rule)
	{
		if (rule.isAlwaysHide())
		{
			return true;
		}
		if (rule.getAction() == SafetyAction.HIDE)
		{
			return true;
		}
		return rule.getCategory() == SafetyCategory.XP_TRAP
			&& config.xpTrapMode() == XpTrapMode.HIDE_AND_WARN;
	}

	private boolean packEnabled(SafetyRule rule)
	{
		switch (rule.getCategory())
		{
			case PRAYER:
				return config.hidePrayerXp();
			case COMBAT_TRAINING:
				return config.hideCombatTraining();
			case NPC_MISCLICK:
				return config.hideNpcMisclicks();
			case XP_TRAP:
				return config.xpTrapProtection();
			default:
				return false;
		}
	}

	private void rateLimitedChat(String message, String key)
	{
		Instant now = Instant.now();
		Instant last = lastWarn.get(key);
		if (last != null && Duration.between(last, now).compareTo(WARN_COOLDOWN) < 0)
		{
			return;
		}
		lastWarn.put(key, now);
		chat(message);
	}

	private void chat(String message)
	{
		String formatted = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("[SG] " + message)
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(formatted)
			.build());
	}

	void reset()
	{
		lastWarn.clear();
		hideTabletCraftButtons(false);
	}
}

package com.skillerguard;

import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.Quest;

/**
 * Combat-XP quests keyed by {@link Quest}. Journal widgets and Quest Helper still
 * expose titles, which are matched to {@link Quest#getName()}.
 */
public final class QuestDenylist
{
	static final String OBSERVATORY_REASON =
		"Unsure if 2018 skip is level-1 skill or level-3 account — proceed at your own risk";

	private static final Map<Quest, String> BY_QUEST = buildQuests();
	private static final Map<String, String> BY_TITLE = buildTitles();

	private QuestDenylist()
	{
	}

	public static String reasonFor(Quest quest)
	{
		return quest == null ? null : BY_QUEST.get(quest);
	}

	public static boolean isDisclaimerTitle(String title)
	{
		return title != null && !title.isEmpty()
			&& normalize(title).equals(normalize(Quest.OBSERVATORY_QUEST.getName()));
	}

	public static String reasonForTitle(String title)
	{
		if (title == null || title.isEmpty())
		{
			return null;
		}
		return BY_TITLE.get(normalize(title));
	}

	public static String normalize(String title)
	{
		String t = title.trim().toLowerCase(Locale.ROOT);
		if (t.startsWith("the "))
		{
			t = t.substring(4);
		}
		return t;
	}

	static Map<String, String> reasons()
	{
		return BY_TITLE;
	}

	private static void put(Map<Quest, String> map, Quest quest, String reason)
	{
		map.merge(quest, reason, (a, b) -> a.contains(b) ? a : a + "; " + b);
	}

	private static Map<Quest, String> buildQuests()
